def solve(inputs: dict) -> float:
    X = inputs['X']
    rounds = inputs['rounds']

    # Keep operations within 32-bit range
    mask_32 = (1 << 32) - 1

    for _ in range(rounds):
        X ^= (X << 13) & mask_32
        X ^= (X >> 9) & mask_32
        X ^= (X << 17) & mask_32
        X &= mask_32

    return float(X)
